  if path == "" {
    raise "Empty path"
  }

  println("Processing file...")
  // Defer will run even if we return early or raise an error
}

fn main {
  try {
    process_file!("test.txt")
  } catch {
    e => println("Error: \{e}")
  }
  // "Closing file" is printed before this point
}
```

