### Generic Functions

```moonbit
fn identity[T](x : T) -> T {
  x
}

fn first[T](arr : Array[T]) -> T? {
  if arr.length() > 0 {
    Some(arr[0])
  } else {
    None
  }
}

fn swap[T](tuple : (T, T)) -> (T, T) {
  let (a, b) = tuple
  (b, a)
}

fn main {
  println(identity(42))
  println(identity("hello"))

  let numbers = [1, 2, 3]
  match first(numbers) {
    Some(x) => println("First: \{x}")
    None => println("Empty array")
  }

  let swapped = swap((1, 2))
  println("Swapped: \{swapped}")
}
```

